26	// A-16 (DEVDESK-143), the cross-cutting guard, started with the :jobs pilot
27	// (DEVDESK-142).
28	//
29	// The guard answers one question for every view the router can build: is it on
30	// the activity column, is it waiting for its migration, or is it exempt for a
31	// stated reason? A view that is none of the three fails the test by name. For a
32	// migrated view it also checks the column, the help legend, the retired
33	// mechanisms in its declared sources (including its own ticks), and the footer
34	// of its selected row. Declared exceptions may only shrink, and follow their
35	// stories: pendingTables here, declaredRowChains in animation_guard_test.go.
36	
37	// activityView is what a migrated view exposes to the guard: read-only tables,
38	// keyed "<view>/<table>".
39	type activityView interface {
40		ActivityTables() map[string]datatable.ActivityTable
41	}
42	
43	// migratedTables are the tables already on the activity column, by view.
44	var migratedTables = map[command.ViewType][]string{
45		command.ViewJobs:         {"jobs/runs", "jobs/targets"},
46		command.ViewWorkspaces:   {"ws"},
47		command.ViewSecurity:     {"sec/inventory"},
48		command.ViewOCIResources: {"oci/images"},
49		command.ViewGitExplorer:  {"explorer/tree", "explorer/clone-list"},
50		command.ViewTemplates:    {"templates"},
51	}
