53	// pendingTable is a table that still has to move to the activity column.
54	type pendingTable struct {
55		Table string
56		View  command.ViewType
57		Story string
58	}
59	
60	// pendingTables may only shrink: each migration story removes its own entries.
61	var pendingTables = []pendingTable{
62		{"oci/registry-browser", command.ViewOCIResources, "A-09a2"},
63		{"oci/networks", command.ViewOCIResources, "A-09b"},
64		{"oci/volumes", command.ViewOCIResources, "A-09b"},
