165	// Criterion 6: every view the router builds is migrated, pending or exempt.
166	func TestActivityGuardEveryViewIsClassified(t *testing.T) {
167		for _, name := range command.AllViewNames() {
168			vt := command.ViewType(name)
169			t.Run(name, func(t *testing.T) {
170				for _, p := range classificationProblems(vt, migratedTables, pendingTables, exemptViews) {
171					t.Errorf("view %q is %s: classify it in activity_guard_test.go", vt, p)
172				}
173			})
174		}
