177	// The logic itself, on a fictitious view that is partly migrated.
178	func TestActivityGuardClassificationLogic(t *testing.T) {
179		const v command.ViewType = "fiction"
180		pending := []pendingTable{{"fiction/b", v, "A-99"}}
181		tests := []struct {
182			name     string
183			migrated map[command.ViewType][]string
184			pending  []pendingTable
185			exempt   map[command.ViewType]string
186			problems int
187			stale    []string
188			reported []string
189		}{
190			{"partly migrated is fine", map[command.ViewType][]string{v: {"fiction/a"}}, pending, nil, 0, nil, []string{"fiction/a"}},
191			{"unclassified fails", nil, nil, nil, 1, nil, nil},
192			{"same table both ways fails", map[command.ViewType][]string{v: {"fiction/b"}}, pending, nil, 1, []string{"fiction/b"}, []string{"fiction/b"}},
193			{"exempt and pending fails", nil, pending, map[command.ViewType]string{v: "why"}, 1, nil, nil},
194			{"pending table not reported is not stale", map[command.ViewType][]string{v: {"fiction/a"}}, pending, nil, 0, nil, []string{"fiction/a"}},
195		}
196		for _, tt := range tests {
197			t.Run(tt.name, func(t *testing.T) {
198				if got := classificationProblems(v, tt.migrated, tt.pending, tt.exempt); len(got) != tt.problems {
199					t.Errorf("problems = %v, want %d", got, tt.problems)
200				}
201				if got := staleExceptions(v, tt.reported, tt.pending); !equalStrings(got, tt.stale) {
202					t.Errorf("stale = %v, want %v", got, tt.stale)
203				}
204			})
205		}
206	}
207	
208	func equalStrings(a, b []string) bool {
209		if len(a) != len(b) {
210			return false
211		}
212		for i := range a {
213			if a[i] != b[i] {
214				return false
215			}
216		}
217		return true
218	}
