264	// Criterion 6, other direction: a view that reports a table still listed as
265	// pending has migrated it; the exception must go. An exempt view must report
266	// none at all.
267	func TestActivityGuardNoStaleException(t *testing.T) {
268		for _, name := range command.AllViewNames() {
269			vt := command.ViewType(name)
270			_, isExempt := exemptViews[vt]
271			if !isExempt && len(pendingViews()[vt]) == 0 {
272				continue
273			}
274			t.Run(name, func(t *testing.T) {
275				av, ok := builtView(t, vt).(activityView)
276				if !ok {
277					return
278				}
279				if isExempt {
280					t.Errorf("view %q exposes ActivityTables() but is exempt: move it out of exemptViews", vt)
281				}
282				reported := sortedKeys(av.ActivityTables())
283				if stale := staleExceptions(vt, reported, pendingTables); len(stale) > 0 {
284					t.Errorf("view %q reports %v, still listed as pending: remove the exception", vt, stale)
285				}
286			})
287		}
288	}
