332		command.ViewOCIResources: {
333			"ui/oci_resources/activity.go", "ui/oci_resources/table.go", "ui/oci_resources/jobs.go",
334			"ui/oci_resources/images.go", "ui/oci_resources/results.go", "ui/oci_resources/view.go",
335		},
