342	// sourceDeclarationProblems says what is wrong with the link between migrated
343	// views and the sources scanned for them, empty when it is fine. files are the
344	// paths relative to internal/ of every non-test source file.
345	func sourceDeclarationProblems(migrated map[command.ViewType][]string, sources map[command.ViewType][]string, files []string) []string {
346		var problems []string
347		for vt := range migrated {
348			if len(sources[vt]) == 0 {
349				problems = append(problems, fmt.Sprintf("view %q is migrated but declares no source to scan in migratedSources", vt))
350			}
351		}
352		for vt, prefixes := range sources {
353			if len(migrated[vt]) == 0 {
354				problems = append(problems, fmt.Sprintf("view %q has sources in migratedSources but is not migrated (migratedTables)", vt))
355			}
356			for _, p := range prefixes {
357				if !anyHasPrefix(files, p) {
358					problems = append(problems, fmt.Sprintf("view %q: source prefix %q matches no file", vt, p))
359				}
360			}
361		}
362		sort.Strings(problems)
363		return problems
364	}
365	
366	func anyHasPrefix(files []string, prefix string) bool {
367		for _, f := range files {
368			if prefix != "" && strings.HasPrefix(f, prefix) {
369				return true
370			}
371		}
372		return false
373	}
