// activityGlyphs are the runes of internal/ui/indicator; a view takes them from
// indicator.Glyph and never spells one.
const activityGlyphs = "●○◴⊗◐◕◉⊘⊖◌"

// declaredViewTicks are the tea.Tick / tea.Every calls a migrated view may

content.content:
420	// declaredViewTicks are the tea.Tick / tea.Every calls a migrated view may
421	// still make, keyed "<file relative to internal/>:<function>" with the reason.
422	// Empty today: the router's one tick animates every row (DEVDESK-139). The list
423	// may only shrink.
424	var declaredViewTicks = map[string]string{}
425	
426	// declaredGlyphConstants are the constants a migrated view may still define with
427	// an activity glyph in them, keyed "<file relative to internal/>:<constant>" with
428	// the reason (DEVDESK-144, decision Q4-A). The exception is the constant, not the
429	// file: any other literal in the same file is still rejected, so the help text
430	// has to build its sentence from the constant. The list may only shrink.
431	var declaredGlyphConstants = map[string]string{
432		"ui/workspaces/view.go:gitMarkNoUpstream": "git marker for a branch with no upstream; it is a git fact, not a row state, and ws never shows the cancelled state, so nothing on screen is ambiguous (changing the marker is a UX ticket of its own)",
433	}
434	
435	// finding is one retired mechanism found in a source file.
436	type finding struct {
437		Pos  token.Position // file:line:column
438		What string
439	}
440	
441	// bubbleTeaName returns the local name file gives the bubbletea import: its
442	// alias, "." for a dot import, "tea" when unnamed, or "" when the file does not
443	// import it (or blank-imports it). A different package that happens to be
444	// called tea is therefore not mistaken for it.
445	func bubbleTeaName(file *ast.File) string {
446		for _, imp := range file.Imports {
447			path, err := strconv.Unquote(imp.Path.Value)
448			if err != nil || path != "github.com/charmbracelet/bubbletea" {
449				continue
450			}
451			switch {
452			case imp.Name == nil:
453				return "tea"
454			case imp.Name.Name == "_":
455				return ""
456			default:
457				return imp.Name.Name
458			}
459		}
460		return ""
461	}
462	
463	// retiredMechanisms reports, in a migrated view's file, every retired
464	// mechanism: AdvanceSpinner, a StatusColumn: key, a frame field, an activity
465	// glyph literal, and any reference to bubbletea's Tick / Every (under whatever name the file
466	// imports it) outside declaredViewTicks.
467	// rel is the file's path relative to internal/; it is the key of a declared tick.
468	// RenderedFrame (a method of the viewport frame) is allowed.
469	func retiredMechanisms(fset *token.FileSet, file *ast.File, rel string) []finding {
470		var out []finding
471		report := func(pos token.Pos, what string) {
472			out = append(out, finding{Pos: fset.Position(pos), What: what})
473		}
474		tea := bubbleTeaName(file)
475		selectors := map[*ast.Ident]bool{} // identifiers seen as the Sel of a selector
476		// reportTick flags any reference to bubbletea's Tick / Every, called or not
477		// (`var tick = tea.Tick` is as much a tick as `tea.Tick(...)`), unless the
478		// enclosing "<file>:<function>" is declared.
479		reportTick := func(pos token.Pos, fn, name string) {
480			if name != "Tick" && name != "Every" {
481				return
482			}
483			if _, declared := declaredViewTicks[rel+":"+fn]; !declared {
484				report(pos, "reference to bubbletea's "+name+" (a view's rows are animated by the router's tick)")
485			}
486		}
487		isFrame := func(name string) bool {
488			return name == "Frame" || name == "frame" || name == "SpinnerFrame"
489		}
490		visit := func(fn string) func(ast.Node) bool {
491			return func(n ast.Node) bool {
492				switch x := n.(type) {
493				case *ast.CallExpr:
494					sel, ok := x.Fun.(*ast.SelectorExpr)
495					if !ok {
496						break
497					}
498					if sel.Sel.Name == "AdvanceSpinner" {
499						report(x.Pos(), "call to AdvanceSpinner")
500					}
501				case *ast.KeyValueExpr:
502					if id, ok := x.Key.(*ast.Ident); ok {
503						if id.Name == "StatusColumn" {
504							report(id.Pos(), "StatusColumn: key")
505						}
506						if isFrame(id.Name) {
507							report(id.Pos(), "frame field "+id.Name+": set")
508						}
509					}
510				case *ast.Field:
511					for _, id := range x.Names {
512						if isFrame(id.Name) {
513							report(id.Pos(), "frame field "+id.Name)
514						}
515					}
516				case *ast.Ident:
517					// Dot import: a bare Tick / Every that no declaration in the file binds.
518					if tea == "." && x.Obj == nil && !selectors[x] {
519						reportTick(x.Pos(), fn, x.Name)
520					}
521				case *ast.SelectorExpr:
522					selectors[x.Sel] = true
523					if pkg, ok := x.X.(*ast.Ident); ok && tea != "" && tea != "." && pkg.Name == tea {
524						reportTick(x.Pos(), fn, x.Sel.Name)
525					}
526					if isFrame(x.Sel.Name) {
527						report(x.Sel.Pos(), "frame selector ."+x.Sel.Name)
528					}
529				case *ast.BasicLit:
530					if x.Kind == token.STRING || x.Kind == token.CHAR {
531						s, err := strconv.Unquote(x.Value)
532						if x.Kind == token.CHAR {
533							var q rune
534							q, _, _, err = strconv.UnquoteChar(x.Value[1:len(x.Value)-1], '\'')
535							s = string(q)
536						}
537						if err == nil && strings.ContainsAny(s, activityGlyphs) {
538							report(x.Pos(), "activity glyph written as a literal "+x.Value+" (use indicator.Glyph)")
539						}
540					}
541				}
542				return true
543			}
544		}
545		for _, decl := range file.Decls {
546			fn := ""
547			if fd, ok := decl.(*ast.FuncDecl); ok {
548				fn = fd.Name.Name
549			}
550			if gd, ok := decl.(*ast.GenDecl); ok && gd.Tok == token.CONST {
551				for _, spec := range gd.Specs {
552					if isDeclaredGlyphConstant(rel, spec) {
553						continue
554					}
555					ast.Inspect(spec, visit(fn))
556				}
557				continue
558			}
559			ast.Inspect(decl, visit(fn))
560		}
561		return out
562	}
563	
564	// isDeclaredGlyphConstant reports whether spec defines only constants declared in
565	// declaredGlyphConstants for the file rel.
566	func isDeclaredGlyphConstant(rel string, spec ast.Spec) bool {
567		vs, ok := spec.(*ast.ValueSpec)
568		if !ok || len(vs.Names) == 0 {
569			return false
570		}
571		for _, id := range vs.Names {
572			if _, declared := declaredGlyphConstants[rel+":"+id.Name]; !declared {
573				return false
574			}
575		}
576		return true
577	}
